VALUES
  (
    2864,
    38,
    '{\"email\":\"ak943771@gmail.com\",\"qid\":\"23030669\",\"course\":\"Btech\",\"year\":\"3\",\"name\":\"ANKIT THAKUR\",\"problem\":\"Schools generate large amounts of academic and operational data such as attendance, classes, assessments, and workload, but this data remains fragmented across multiple systems, viewed in isolation, and rarely analyzed over time. As a result, early warning signals like declining attendance, missed classes, or delayed evaluations go unnoticed until outcomes are affected, forcing institutions to rely on reactive decision-making instead of proactive intervention.\",\"solution\":\"Unified Campus Grid (UCG) provides a structured three-layer system where the Eye captures all school activities as time-stamped events to create unified visibility, the Brain analyzes this data to detect patterns and generate explainable insights, and the Action layer enables human-approved, structured responses, allowing schools to identify issues early and respond effectively before they escalate.\",\"target_customer\":\"School, University, College \\n\\nLater on we will upgrade the system for Industries \"}',
    'pending',
    '2026-03-20 09:25:38',
    NULL,
    'wg8lx3diu788yw02tohzgi'
  );
